//! 🏪️ Original instance lanes share one caller through authored genesis, native replay and cancellation.
use semio_framework_plugin_decl_app::ArtifactApp;
use semio_framework_plugin_ownership::original_store_genesis::{OriginalStoreGenesis,OriginalStoreGenesisOwner,OriginalStoreSlot};
use semio_framework_plugin_interaction::mutations::InteractionConfigMutation;
use semio_framework_os_kernel as store;
use semio_framework_job::{StepContext,OriginalTurnFailure,OriginalSourceBinding,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retirement::controlled::ControlledRetirement};
use std::mem::{size_of,ManuallyDrop};
pub use semio_framework_plugin_decl_app::OriginalArtifactAppBirth;
/// 🧳️ These are the same four native Stores produced under the instance constructor's original operation.
pub struct OriginalArtifactStores<A:ArtifactApp>{pub document:OriginalStoreSlot<A::Snapshot,A::Mutation>,pub config:OriginalStoreSlot<A::Config,A::ConfigMutation>,pub draft:OriginalStoreSlot<A::Draft,A::DraftMutation>,pub interaction:OriginalStoreSlot<store::InteractionState,InteractionConfigMutation>,binding:OriginalSourceBinding}
struct Metadata{labels:[String;4],actor:Option<store::ActorId>}
semio_framework_value::artifact_retire_struct!(Metadata{labels,actor});
/// 🌱️ No Store or default source is recreated while the next original lane is awaiting its caller.
pub struct OriginalArtifactStoreSet<A:OriginalArtifactAppBirth>{
 metadata:ManuallyDrop<Option<Metadata>>,metadata_close:Option<ControlledRetirement<Metadata>>,returned:Option<String>,returned_close:Option<ControlledRetirement<String>>,
 document_birth:Option<Box<OriginalStoreGenesis<A::DocumentGenesis>>>,config_birth:Option<Box<OriginalStoreGenesis<A::ConfigGenesis>>>,draft_birth:Option<Box<OriginalStoreGenesis<A::DraftGenesis>>>,interaction_birth:Option<Box<OriginalStoreGenesis<A::InteractionGenesis>>>,
 document:ManuallyDrop<Option<Box<store::ArtifactStore<A::Snapshot,A::Mutation>>>>,config:ManuallyDrop<Option<Box<store::ConfigStore<A::Config,A::ConfigMutation>>>>,draft:ManuallyDrop<Option<Box<store::DraftStore<A::Draft,A::DraftMutation>>>>,interaction:ManuallyDrop<Option<Box<store::ConfigStore<store::InteractionState,InteractionConfigMutation>>>>,binding:OriginalSourceBinding,stage:u8,closing:bool,
}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
impl<A:OriginalArtifactAppBirth> OriginalArtifactStoreSet<A>{
 /// 📏️ Prices only exact instance metadata and its retained four-lane shell.
 pub fn birth_demands(instance:&str)->Result<RetirementDemand,ValueError>{let labels=instance.len().checked_mul(4).and_then(|n|n.checked_add(7+6+12)).ok_or_else(||invalid("original instance identity extent overflow"))?;Ok(RetirementDemand{copy_bytes:2*size_of::<Self>()+labels,capacity_bytes:size_of::<Self>()+labels,depth:1,..Default::default()})}
 /// 🎟️ Captures authored instance identity and the actual actor lease under this caller's paid source admission.
 pub fn admit(instance:&str,actor:&store::ActorId,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if instance.is_empty()||output.is_some(){return Err(invalid("original instance stores require a named source and empty output").into())}let d=Self::birth_demands(instance)?;let binding=OriginalSourceBinding::borrow(cx);let grant=cx.retained_grant();admit_original_construction(cx,output,construction(d),|_|{let(actor,_)=actor.0.admit_clone(grant)?;let suffixes=["","-config","-draft","-interaction"];let labels=std::array::from_fn(|index|{let mut label=String::with_capacity(instance.len()+suffixes[index].len());label.push_str(instance);label.push_str(suffixes[index]);label});let value=Self{metadata:ManuallyDrop::new(Some(Metadata{labels,actor:Some(store::ActorId(actor))})),metadata_close:None,returned:None,returned_close:None,document_birth:None,config_birth:None,draft_birth:None,interaction_birth:None,document:ManuallyDrop::new(None),config:ManuallyDrop::new(None),draft:ManuallyDrop::new(None),interaction:ManuallyDrop::new(None),binding,stage:0,closing:false};Ok((Box::new(value),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))})?;Ok(output.is_some())}
 /// 📏️ Quotes release of the terminal retained constructor frame.
 pub fn boxed_release_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Box<Self>>(),release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 /// 📍️ Reports the exact lane and native child stage without acquiring another owner.
 pub fn progress(&self)->(u8,Option<(u8,bool,bool)>,bool){(self.stage,self.document_birth.as_ref().map(|v|v.progress()).or_else(||self.config_birth.as_ref().map(|v|v.progress())).or_else(||self.draft_birth.as_ref().map(|v|v.progress())).or_else(||self.interaction_birth.as_ref().map(|v|v.progress())),self.closing)}
 /// ▶️ Advances one actual original child or one paid metadata handoff.
 pub fn step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx){return Err(invalid("original instance Store source changed its caller").into())}if self.closing||cx.is_cancelled(){self.closing=true;return Ok(false)}if cx.should_yield(){return Ok(false)}if !close_text(&mut self.returned,&mut self.returned_close,cx)?{return Ok(false)}let metadata=self.metadata.as_ref().ok_or_else(||invalid("original instance Store metadata is absent"))?;let actor=metadata.actor.as_ref().unwrap();let ready=match self.stage{0=>advance_lane::<A::DocumentGenesis>(&mut self.document_birth,&mut self.document,&mut self.returned,&metadata.labels[0],actor,cx)?,1=>advance_lane::<A::ConfigGenesis>(&mut self.config_birth,&mut self.config,&mut self.returned,&metadata.labels[1],actor,cx)?,2=>advance_lane::<A::DraftGenesis>(&mut self.draft_birth,&mut self.draft,&mut self.returned,&metadata.labels[2],actor,cx)?,3=>advance_lane::<A::InteractionGenesis>(&mut self.interaction_birth,&mut self.interaction,&mut self.returned,&metadata.labels[3],actor,cx)?,_=>return Ok(true)};if ready{let d=fixed::<u8>();let mut moved=None;admit_original_construction(cx,&mut moved,construction(d),|_|{self.stage+=1;Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}Ok(false)}
 /// 📤️ Moves exactly the initialized four Stores; metadata and constructor shell remain retained for paid closure.
 pub fn take(&mut self,output:&mut Option<OriginalArtifactStores<A>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx)||self.stage!=4||self.closing||output.is_some(){return Err(invalid("original instance Store handoff requires its unchanged ready source").into())}let d=fixed::<OriginalArtifactStores<A>>();admit_original_construction(cx,output,construction(d),|_|{let value=OriginalArtifactStores{binding:self.binding,document:OriginalStoreSlot::from_original(self.document.take().ok_or_else(||invalid("original document Store absent"))?),config:OriginalStoreSlot::from_original(self.config.take().ok_or_else(||invalid("original config Store absent"))?),draft:OriginalStoreSlot::from_original(self.draft.take().ok_or_else(||invalid("original draft Store absent"))?),interaction:OriginalStoreSlot::from_original(self.interaction.take().ok_or_else(||invalid("original interaction Store absent"))?)};self.closing=true;Ok((value,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(output.is_some())}
 /// ♻️ The same caller closes every partial child, privately initialized Store and original metadata on cancellation.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx){return Err(invalid("original instance Store cleanup changed its caller").into())}self.closing=true;if !close_lane::<A::DocumentGenesis>(&mut self.document_birth,cx)?||!close_lane::<A::ConfigGenesis>(&mut self.config_birth,cx)?||!close_lane::<A::DraftGenesis>(&mut self.draft_birth,cx)?||!close_lane::<A::InteractionGenesis>(&mut self.interaction_birth,cx)?{return Ok(false)}if !close_store(&mut self.document,cx)?||!close_store(&mut self.config,cx)?||!close_store(&mut self.draft,cx)?||!close_store(&mut self.interaction,cx)?{return Ok(false)}if !close_text(&mut self.returned,&mut self.returned_close,cx)?{return Ok(false)}if let Some(owner)=self.metadata_close.as_mut(){if owner.terminal_is_empty(){let d=fixed::<Option<ControlledRetirement<Metadata>>>();close_original_retained_step(cx,d,|_|{self.metadata_close=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=owner.next_demand(4096)?;close_original_retained_step(cx,d,|grant|owner.step(grant))?;}return Ok(false)}if self.metadata.is_some(){let d=fixed::<(Metadata,ControlledRetirement<Metadata>)>();close_original_retained_step(cx,d,|_|{let original=self.metadata.take().unwrap();match ControlledRetirement::new(original){Ok(owner)=>self.metadata_close=Some(owner),Err((error,original))=>{*self.metadata=Some(original);return Err(error)}}Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}Ok(self.terminal_is_empty())}
 /// 🕳️ No native lane, private Store or original identity survives the terminal shell.
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.metadata.is_none()&&self.metadata_close.is_none()&&self.returned.is_none()&&self.returned_close.is_none()&&self.document_birth.is_none()&&self.config_birth.is_none()&&self.draft_birth.is_none()&&self.interaction_birth.is_none()&&self.document.is_none()&&self.config.is_none()&&self.draft.is_none()&&self.interaction.is_none()}
}
fn advance_lane<O:OriginalStoreGenesisOwner>(birth:&mut Option<Box<OriginalStoreGenesis<O>>>,store:&mut Option<Box<store::ArtifactStore<O::State,O::Mutation>>>,returned:&mut Option<String>,label:&str,actor:&store::ActorId,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if store.is_none(){if let Some(owner)=birth.as_mut(){if let Some((label,value))=owner.step(cx)?{*returned=Some(label);*store=Some(value);}return Ok(false)}*birth=OriginalStoreGenesis::<O>::admit(label,actor,cx)?;return Ok(false)}close_lane(birth,cx)}
fn close_lane<O:OriginalStoreGenesisOwner>(birth:&mut Option<Box<OriginalStoreGenesis<O>>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(owner)=birth.as_mut()else{return Ok(true)};if !owner.terminal_is_empty(){owner.close_step(cx)?;return Ok(false)}let d=OriginalStoreGenesis::<O>::boxed_release_demands();close_original_retained_step(cx,d,|_|{*birth=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(false)}
fn close_text(source:&mut Option<String>,owner:&mut Option<ControlledRetirement<String>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if let Some(active)=owner.as_mut(){if !active.terminal_is_empty(){let d=active.next_demand(4096)?;close_original_retained_step(cx,d,|grant|active.step(grant))?;}else{let d=fixed::<Option<ControlledRetirement<String>>>();close_original_retained_step(cx,d,|_|{*owner=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}return Ok(false)}if source.is_some(){let d=fixed::<(String,ControlledRetirement<String>)>();close_original_retained_step(cx,d,|_|{*owner=Some(ControlledRetirement::new(source.take().unwrap()).unwrap_or_else(|_|unreachable!("native instance text declares controlled retirement")));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}Ok(true)}
fn close_store<P,M>(source:&mut Option<Box<store::ArtifactStore<P,M>>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P: ::semio_framework_os_kernel::StoreState,M: ::semio_framework_os_kernel::StoreMutationFor<P>{let Some(owner)=source.as_mut()else{return Ok(true)};if owner.close_owned_store_terminal_is_empty(){let mut d=fixed::<Option<Box<store::ArtifactStore<P,M>>>>();d.release_bytes=size_of::<store::ArtifactStore<P,M>>();close_original_retained_step(cx,d,|_|{*source=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;}else{let d=owner.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|owner.close_owned_store_step(grant))?;}Ok(false)}
impl<A:OriginalArtifactAppBirth> Drop for OriginalArtifactStoreSet<A>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native instance Store constructor must close every original source");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.metadata);ManuallyDrop::drop(&mut self.document);ManuallyDrop::drop(&mut self.config);ManuallyDrop::drop(&mut self.draft);ManuallyDrop::drop(&mut self.interaction);}}}}

impl<A:ArtifactApp> OriginalArtifactStores<A>{
 /// 🪪️ Checks the unchanged original constructor source before final instance assembly.
 pub fn matches(&self,cx:&StepContext<'_>)->bool{self.binding.matches(cx)}
}

impl<A:ArtifactApp> OriginalArtifactStores<A>{
 pub fn into_parts(self)->(Box<store::ArtifactStore<A::Snapshot,A::Mutation>>,Box<store::ConfigStore<A::Config,A::ConfigMutation>>,Box<store::DraftStore<A::Draft,A::DraftMutation>>,Box<store::ConfigStore<store::InteractionState,InteractionConfigMutation>>){(self.document.into_original(),self.config.into_original(),self.draft.into_original(),self.interaction.into_original())}
}

impl<A:ArtifactApp> OriginalArtifactStores<A>{
 /// ♻️ Each exact Store payload and its original physical box close before the four-lane source can disappear.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.matches(cx){return Err(invalid("original Store source changed its closing caller").into())}if !self.document.terminal_is_empty(){self.document.close_step(cx)?;return Ok(false)}if !self.config.terminal_is_empty(){self.config.close_step(cx)?;return Ok(false)}if !self.draft.terminal_is_empty(){self.draft.close_step(cx)?;return Ok(false)}if !self.interaction.terminal_is_empty(){self.interaction.close_step(cx)?;return Ok(false)}Ok(true)}
}
